import { test, expect } from '@playwright/test';

test.describe('Active Filter Tags Above Search Results', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display a tag for each active filter above search results', async ({ page }) => {
    // Apply first filter
    const categoryFilter = page.getByRole('button', { name: /category/i });
    await categoryFilter.click();
    const electronicsOption = page.getByRole('option', { name: /electronics/i });
    await electronicsOption.click();

    // Apply second filter
    const priceFilter = page.getByRole('button', { name: /price/i });
    await priceFilter.click();
    const priceRangeOption = page.getByRole('option', { name: /under $500/i });
    await priceRangeOption.click();

    // Apply third filter
    const brandFilter = page.getByRole('button', { name: /brand/i });
    await brandFilter.click();
    const appleOption = page.getByRole('option', { name: /apple/i });
    await appleOption.click();

    // Verify filter tags are displayed
    const filterTags = page.getByRole('region', { name: /active filters/i });
    await expect(filterTags).toBeVisible();

    const electronicsTag = page.getByText('Electronics');
    await expect(electronicsTag).toBeVisible();

    const priceTag = page.getByText('Under $500');
    await expect(priceTag).toBeVisible();

    const appleTag = page.getByText('Apple');
    await expect(appleTag).toBeVisible();

    // Verify tags have remove buttons
    const electronicsRemoveButton = page.getByRole('button', { name: /remove filter/i });
    await expect(electronicsRemoveButton).toBeVisible();

    const priceRemoveButton = page.getByRole('button', { name: /remove filter/i });
    await expect(priceRemoveButton).toBeVisible();

    const appleRemoveButton = page.getByRole('button', { name: /remove filter/i });
    await expect(appleRemoveButton).toBeVisible();

    // Verify search results are displayed below tags
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();
  });

  test('should not display filter tags when no filters are active', async ({ page }) => {
    // Verify filter tags region is not visible initially
    const filterTagsRegion = page.getByRole('region', { name: /active filters/i });
    await expect(filterTagsRegion).not.toBeVisible();

    // Verify no filter tags exist
    const allFilterTags = page.getByRole('region', { name: /active filters/i }).locator('[data-testid="filter-tag"]');
    await expect(allFilterTags).toHaveCount(0);

    // Verify search results are still displayed
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Apply a filter and verify tag appears
    const categoryFilter = page.getByRole('button', { name: /category/i });
    await categoryFilter.click();
    const electronicsOption = page.getByRole('option', { name: /electronics/i });
    await electronicsOption.click();

    // Verify tag appears
    const electronicsTag = page.getByText('Electronics');
    await expect(electronicsTag).toBeVisible();

    // Verify tag has remove button
    const electronicsRemoveButton = page.getByRole('button', { name: /remove filter/i });
    await expect(electronicsRemoveButton).toBeVisible();
  });
});
